import os, json, time
import numpy as np
try:
    from scipy.optimize import nnls
except Exception:
    nnls = None

N = 26
R_MIN = 1e-6
SAFETY = 1e-9
TOLS = [1e-9, 1e-8]
K_TOL_MAP = {1e-9: 25, 1e-8: 15}

P_C = 'storage/noesis/latest_centers.txt'
P_R = 'storage/noesis/latest_radii.txt'
OUT_DIR = 'storage/noesis/exports'
OUT_JSON = os.path.join(OUT_DIR, 'operator_gate_dual_tol_kkt_latest.json')
OUT_TOP  = os.path.join(OUT_DIR, 'kkt_top_pairs_by_lambda_latest.json')

def _ensure_dir(p): os.makedirs(p, exist_ok=True)

def load_snapshot():
    c = np.loadtxt(P_C, dtype=float).reshape(N,2)
    r = np.loadtxt(P_R, dtype=float).reshape(N,)
    if np.any(r <= 0): raise ValueError("non-positive radii")
    return c, r

def slacks(c, r):
    x = c[:,0]; y = c[:,1]
    s_xL = x - r
    s_xR = 1.0 - x - r
    s_yB = y - r
    s_yT = 1.0 - y - r
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    s_pairs = dist - (r[:,None] + r[None,:])
    return (s_xL, s_xR, s_yB, s_yT), s_pairs

def active_sets(c, r, tol):
    (s_xL, s_xR, s_yB, s_yT), s_pairs = slacks(c, r)
    b = []
    for i in range(N):
        if s_xL[i] <= tol: b.append((i, 'xL'))
        if s_xR[i] <= tol: b.append((i, 'xR'))
        if s_yB[i] <= tol: b.append((i, 'yB'))
        if s_yT[i] <= tol: b.append((i, 'yT'))
    p = []
    for i in range(N):
        for j in range(i+1, N):
            if s_pairs[i,j] <= tol:
                p.append((i, j))
    return b, p

def boundary_mask(c, r, tol):
    (s_xL, s_xR, s_yB, s_yT), _ = slacks(c, r)
    return (s_xL <= tol) | (s_xR <= tol) | (s_yB <= tol) | (s_yT <= tol)

def grad_row_boundary(i, kind):
    row = np.zeros(3*N, dtype=float)
    xi = 3*i; yi = xi + 1; ri = xi + 2
    if kind == 'xL':
        row[xi] = 1.0;  row[ri] = -1.0
    elif kind == 'xR':
        row[xi] = -1.0; row[ri] = -1.0
    elif kind == 'yB':
        row[yi] = 1.0;  row[ri] = -1.0
    elif kind == 'yT':
        row[yi] = -1.0; row[ri] = -1.0
    return row

def grad_row_pair(c, i, j):
    row = np.zeros(3*N, dtype=float)
    xi = 3*i; yi = xi + 1; ri = xi + 2
    xj = 3*j; yj = xj + 1; rj = xj + 2
    dx = c[i,0] - c[j,0]; dy = c[i,1] - c[j,1]
    d = float(np.hypot(dx, dy))
    if d > 1e-15:
        invd = 1.0 / d
        row[xi] = dx*invd; row[yi] = dy*invd
        row[xj] = -dx*invd; row[yj] = -dy*invd
    row[ri] = -1.0; row[rj] = -1.0
    return row

def kkt_nnls(c, r, tol):
    # Build Jacobian rows for active constraints at tol
    b_act, p_act = active_sets(c, r, tol)
    rows = []
    ids  = []  # ('b',i,kind) or ('p',i,j)
    for (i, kind) in b_act:
        rows.append(grad_row_boundary(i, kind)); ids.append(('b', i, kind))
    for (i, j) in p_act:
        rows.append(grad_row_pair(c, i, j));    ids.append(('p', i, j))
    if not rows:
        return [], np.array([]), []

    J = np.vstack(rows)            # (M, 3N)
    A = J.T                        # (3N, M)
    b = np.zeros(3*N, dtype=float) # -∇f = e_r
    b[2::3] = 1.0

    if nnls is not None:
        lam, _ = nnls(A, b)
    else:
        # Fallback: unconstrained least squares then clamp to >=0
        lam = np.linalg.lstsq(A, b, rcond=None)[0]
        lam = np.maximum(lam, 0.0)
    return ids, lam, J

def rank_pairs_by_lambda(ids, lam, interior_mask):
    # Aggregate λ for pair constraints only; return list of (i,j,lambda)
    pairs = []
    for idx, tag in enumerate(ids):
        if tag[0] != 'p': continue
        i, j = tag[1], tag[2]
        if interior_mask[i] and interior_mask[j]:
            pairs.append((i, j, float(lam[idx])))
    pairs.sort(key=lambda t: t[2], reverse=True)
    return pairs

def _orient(a, b, c):
    return (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])

def segments_cross(p1, p2, q1, q2):
    o1 = _orient(p1, p2, q1); o2 = _orient(p1, p2, q2)
    o3 = _orient(q1, q2, p1); o4 = _orient(q1, q2, p2)
    return (o1*o2 < 0) and (o3*o4 < 0)

def construct_packing():
    c, r = load_snapshot()
    # Common interior requirement: non-boundary at both tolerances
    interior_boths = None
    tops_by_tol = {}
    for tol in TOLS:
        bmask = boundary_mask(c, r, tol)
        interior = ~bmask
        if interior_boths is None:
            interior_boths = interior.copy()
        else:
            interior_boths = interior_boths & interior

    ranked_pairs = {}
    for tol in TOLS:
        ids, lam, J = kkt_nnls(c, r, tol)
        pairs = rank_pairs_by_lambda(ids, lam, interior_boths)
        K = K_TOL_MAP[tol]
        ranked_pairs[str(tol)] = [{'i':i, 'j':j, 'lambda':lam_} for (i,j,lam_) in pairs[:K]]

    # Intersect top-K sets across tolerances
    sets = []
    for tol in TOLS:
        K = K_TOL_MAP[tol]
        s = set((d['i'], d['j']) for d in ranked_pairs[str(tol)][:K])
        sets.append(s)
    common = set.intersection(*sets) if sets else set()

    # Search for crossing-quads among common top pairs
    common_list = list(common)
    quads = []
    m = len(common_list)
    for a in range(m):
        i, j = common_list[a]
        pi, pj = c[i], c[j]
        for b in range(a+1, m):
            k, l = common_list[b]
            if len({i,j,k,l}) < 4: continue
            pk, pl = c[k], c[l]
            if segments_cross(pi, pj, pk, pl):
                quads.append({'quad': [i, j, k, l]})
    report = {
        'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
        'policy': {'tols': TOLS, 'K_map': K_TOL_MAP, 'interior_requirement': 'non-boundary at both tol'},
        'has_candidate': bool(quads),
        'num_candidates': len(quads),
        'example_quads': quads[:5],
        'common_pairs_count': len(common)
    }

    _ensure_dir(OUT_DIR)
    try:
        with open(OUT_JSON, 'w') as f:
            json.dump(report, f, indent=2)
        with open(OUT_TOP, 'w') as f:
            json.dump({'ranked_pairs_by_tol': ranked_pairs}, f, indent=2)
    except Exception:
        pass

    # Return SOTA snapshot with tiny shrink
    r_out = np.maximum(r - SAFETY, R_MIN)
    return c.astype(float), r_out.astype(float)
